namespace Encspect.Formats.Aac;

// What the nodes of a raw data block's elements are: ISO/IEC 14496-3 4.4.2 gives their syntax, 4.5.2
// their semantics and 4.6 the tools they control.
internal static partial class Explain
{
    public const string ElementId = "id_syn_ele: which syntax element follows: 0 SCE, 1 CPE, 2 CCE, 3 LFE, 4 DSE, 5 PCE, 6 FIL, 7 END (ISO/IEC 14496-3 4.4.2).";
    public const string ChannelElement = "A channel element: a single channel (SCE), an LFE channel (LFE) or a channel pair (CPE), with the coded spectrum of each channel (ISO/IEC 14496-3 4.4.2).";
    public const string EndElement = "The END element, which closes the raw data block; byte alignment bits may follow (ISO/IEC 14496-3 4.4.2).";
    public const string ByteAlignment = "Bits after the END element up to the next byte boundary of the raw data block (ISO/IEC 14496-3 4.4.2, byte_alignment).";
    public const string HasCommonWindow = "common_window: whether both channels of the pair share one ics_info, which mid/side stereo needs (ISO/IEC 14496-3 4.4.2).";
    public const string MsMaskPresent = "ms_mask_present: 0 codes the pair as left/right, 1 sends a mid/side flag per band, 2 codes every band as mid/side; 3 is reserved (ISO/IEC 14496-3 4.5.2, 4.6.8.1).";
    public const string MidSideBands = "The bands whose ms_used flag is set, which the pair codes as mid/side instead of left/right; on intensity stereo bands the flag inverts the sign instead (ISO/IEC 14496-3 4.6.8.1, 4.6.8.2).";
    public const string ChannelStream = "One channel's individual_channel_stream: its global gain, window information, sections, scalefactors, tools and spectral data (ISO/IEC 14496-3 4.4.2).";
    public const string GlobalGain = "global_gain: the first scalefactor of the channel, from which the others are coded as differences; it sets the overall quantizer step (ISO/IEC 14496-3 4.6.2).";
    public const string IcsInfo = "ics_info: the window sequence and shape, how many scalefactor bands are coded (max_sfb), the grouping of short windows and the predictor data (ISO/IEC 14496-3 4.4.2).";
    public const string IcsReservedBit = "ics_reserved_bit, which must be 0 (ISO/IEC 14496-3 4.5.2).";
    public const string WindowSequence = "window_sequence: 0 one long window, 1 a long start window before short ones, 2 eight short windows, 3 a long stop window after them (ISO/IEC 14496-3 4.5.2, 4.6.11).";
    public const string WindowShape = "window_shape: 0 sine, 1 Kaiser-Bessel derived (KBD); the shape of the transform window's slopes (ISO/IEC 14496-3 4.5.2, 4.6.11).";
    public const string MaxSfb = "max_sfb: how many scalefactor bands, from the lowest, are coded; the bands above it are zero, which sets the coded bandwidth (ISO/IEC 14496-3 4.5.2).";
    public const string ScaleFactorGrouping = "scale_factor_grouping: for each of the last seven short windows, whether it joins the previous window's group, which shares scalefactors and sections (ISO/IEC 14496-3 4.5.2).";
    public const string HasPredictorData = "predictor_data_present: whether AAC Main prediction or AAC LTP long-term prediction data follows (ISO/IEC 14496-3 4.4.2).";
    public const string HasPredictorReset = "predictor_reset: whether a group of AAC Main predictors is reset in this frame (ISO/IEC 14496-3 4.5.2).";
    public const string PredictorResetGroup = "predictor_reset_group_number: which of the 30 groups of predictors is reset, 1 to 30 (ISO/IEC 14496-3 4.5.2).";
    public const string PredictionUsed = "prediction_used: the bands in which AAC Main prediction from earlier frames is applied (ISO/IEC 14496-3 4.5.2).";
    public const string HasLtpData = "ltp_data_present: whether long-term prediction data follows for the channel (ISO/IEC 14496-3 4.4.2, AAC LTP).";
